1	import React, { useId } from 'react';
2	import { chakra, Drawer, DrawerOverlay, useMultiStyleConfig, useModalContext, ModalFocusScope } from '@chakra-ui/react';
3	import type { SystemStyleObject } from '@chakra-ui/react';
4	import { motion } from 'framer-motion';
5	import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
6	
7	const ZIMM_DRAWER_RECIPE = 'ZimmDrawer';
8	
9	// framer-motion's `Transition.ease` wants a literal, mutable 4-tuple (`BezierDefinition`) — a
10	// plain array literal infers as `number[]`, and `as const` infers a *readonly* tuple, neither of
11	// which satisfies it, hence the explicit cast.
12	const BEZIER_SLIDES_EASING = [0.87, 0, 0.13, 1] as [number, number, number, number];
13	// Mirrors theme/foundation/motion.ts's `duration.default` (300ms) and `easing.slides`
14	// (cubic-bezier(0.87, 0, 0.13, 1), "panels and overlays entering the screen") — hand-converted
15	// to framer-motion's shape (seconds, not ms; a bezier tuple, not a CSS `cubic-bezier()` string)
16	// since motion.ts's tokens are CSS-string form and framer-motion doesn't accept that form. One
17	// shared value for both enter and exit — that symmetry is the whole point (SFCC-898).
18	const DRAWER_TRANSITION = { duration: 0.3, ease: BEZIER_SLIDES_EASING };
19	
20	// `motion(chakra.div)` — framer OUTSIDE, chakra INSIDE. This ordering matters: framer's
21	// `motion()` only intercepts its own known animation props (initial/animate/exit/transition/
22	// variants) and forwards everything else straight to the wrapped component, so `transition`
23	// reaches framer-motion directly here. Chakra's OWN internal Drawer does the reverse
24	// (`chakra(Slide)`) — chakra wraps the animated component — and chakra's `shouldForwardProp`
25	// treats any prop literally named `transition` as a CSS shorthand style prop (it's a real
26	// Chakra/styled-system prop name), silently swallowing it before it ever reaches the wrapped
27	// component's real props (confirmed directly in @chakra-ui/system's should-forward-prop.js).
28	// That's why `<DrawerContent transition={...}>` had no effect and why this file no longer uses
29	// Chakra's `<DrawerContent>` at all — SFCC-898's close-animation defect (asymmetric enter/exit;
30	// Chakra's own Slide defaults to a spring-physics enter vs. a fixed 150ms tween exit, per
31	// @chakra-ui/transition's slide.js) can't be fixed through any prop that component exposes.
32	const MotionChakraDiv = motion(chakra.div);
33	
34	// Matches Figma's own named drawer sizes exactly (SFCC-898) — see zimmDrawer.css.ts's
35	// file-level comment for the width/usage table. `xLarge` has no consumer yet (Cart is a full
36	// page today, not a drawer).
37	export type ZimmDrawerSize = 'large' | 'tablet' | 'small' | 'xLarge' | 'mobile';
38	
39	type ZimmDrawerBaseProps = {
40	  /** Whether the drawer is open. */
41	  isOpen: boolean;
42	  /** Called on backdrop click, Escape, and the close button (all via Chakra's Drawer). */
43	  onClose: () => void;
44	  /** Desktop/tablet width variant — see ZimmDrawerSize. Collapses to the mobile treatment
45	   *  below the tablet breakpoint regardless of which value is chosen — see zimmDrawer.css.ts. */
46	  size: ZimmDrawerSize;
47	  children: React.ReactNode;
48	  /** Text style for the title. 'large' applies heading1 (24px, uppercase, Futura Round regular);
49	   *  'small' applies body2Strong (14px bold). Defaults to 'large'. Only relevant when `title`
50	   *  is provided. */
51	  titleStyle?: 'large' | 'small';
52	  /** Element to focus when the drawer closes. Use when the trigger may not have received
53	   *  keyboard focus before opening (e.g. mouse click) — without this Chakra falls back to
54	   *  document.body and AC10 focus-return fails. */
55	  finalFocusRef?: React.RefObject<HTMLElement>;
56	  /** Element to focus when the drawer opens. Overrides Chakra's default (first focusable element
57	   *  in the panel, usually the close button) — use to land focus directly on the primary input. */
58	  initialFocusRef?: React.RefObject<HTMLElement>;
59	};
60	
61	/**
62	 * Exactly one of:
63	 * - `title`       — renders an inline header row (title left, close button right); the drawer's
64	 *                   accessible name is derived from the rendered title element automatically.
65	 * - `labelledBy`  — ID of an existing element that labels the drawer (e.g. ZimmPdpDrawer's own
66	 *                   tab header). Paired with the floating close button.
67	 * - `aria-label`  — explicit string label when neither a visible title nor a separate element
68	 *                   is available.
69	 */
70	type ZimmDrawerProps = ZimmDrawerBaseProps &
71	  (
72	    | { title: string; labelledBy?: never; 'aria-label'?: never }
73	    | { title?: never; labelledBy: string; 'aria-label'?: never }
74	    | { title?: never; labelledBy?: never; 'aria-label': string }
75	  );
76	
77	// Deliberately not named `ZimmDrawerContentProps` — scripts/generateRegistry.mjs's
78	// extractTsProps merges every `*Props`-suffixed type in a file into one component's registry
79	// row when it can't isolate the preferred one (ZimmDrawerProps' multi-line union body isn't
80	// matched by its regex, which can't cross a newline — a documented limitation, not a bug to
81	// patch there). That merge was leaking this internal helper's own fields (ariaLabel,
82	// contentStyles, closeButtonStyles) into ZimmDrawer's public registry entry.
83	type ZimmDrawerContentConfig = {
84	  children: React.ReactNode;
85	  onClose: () => void;
86	  /** Renders an inline header row (title left, close button right) instead of the floating
87	   *  close button when provided — see ZimmDrawerProps' `title` member. */
88	  title?: string;
89	  titleId?: string;
90	  titleStyle?: 'large' | 'small';
91	  labelledBy?: string;
92	  ariaLabel?: string;
93	  contentStyles: SystemStyleObject;
94	  headerStyles: SystemStyleObject;
95	  headerTitleStyles: SystemStyleObject;
96	  closeButtonStyles: SystemStyleObject;
97	};
98	
99	/**
100	 * Replaces Chakra's own `<DrawerContent>` — see the `MotionChakraDiv` comment above for why.
101	 * Reuses Chakra's real dialog/focus/aria mechanics directly (`useModalContext`,
102	 * `ModalFocusScope` — both genuinely public exports, not reaching into Chakra internals) so
103	 * focus trap, initial focus, focus restore, body-scroll lock, and Escape/overlay-click-to-close
104	 * all still come from Chakra exactly as before; only the slide transition itself is now ours.
105	 *
106	 * Renders either an inline title row (title left, close button right) when `title` is passed, or
107	 * a floating close button only — see ZimmDrawer's own docblock for when each is used.
108	 *
109	 * @param props see ZimmDrawerContentConfig
110	 */
111	const ZimmDrawerContent = ({
112	  children,
113	  onClose,
114	  title,
115	  titleId,
116	  titleStyle = 'large',
117	  labelledBy,
118	  ariaLabel,
119	  contentStyles,
120	  headerStyles,
121	  headerTitleStyles,
122	  closeButtonStyles,
123	}: ZimmDrawerContentConfig) => {
124	  const { getDialogProps, getDialogContainerProps } = useModalContext();
125	  const dialogProps = getDialogProps({ 'aria-label': ariaLabel });
126	  // getDialogProps always computes `aria-labelledby` from Chakra's own <DrawerHeader> mount
127	  // state, which ZimmDrawer never renders (no header sub-component in this tree) — so it
128	  // always resolves to undefined regardless of what's passed in above. Set it directly so the
129	  // `title` and `labelledBy` prop variants of ZimmDrawerProps actually work.
130	  if (title && titleId) {
131	    dialogProps['aria-labelledby'] = titleId;
132	  } else if (labelledBy) {
133	    dialogProps['aria-labelledby'] = labelledBy;
134	  }
135	  const containerProps = getDialogContainerProps();
136	
137	  return (
138	    <ModalFocusScope>
139	      <chakra.div {...containerProps} __css={{ position: 'fixed', inset: 0, display: 'flex', zIndex: 'modal' }}>
140	        <MotionChakraDiv
141	          {...dialogProps}
142	          initial={{ x: '100%' }}
143	          animate={{ x: 0 }}
144	          exit={{ x: '100%' }}
145	          transition={DRAWER_TRANSITION}
146	          __css={{ position: 'fixed', top: 0, right: 0, bottom: 0, outline: 0, ...contentStyles }}
147	        >
148	          {title ? (
149	            <chakra.div sx={headerStyles}>
150	              <chakra.span
151	                id={titleId}
152	                sx={headerTitleStyles}
153	                textStyle={titleStyle === 'small' ? 'body2Strong' : 'heading1'}
154	              >
155	                {title}
156	              </chakra.span>
157	              <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
158	            </chakra.div>
159	          ) : (
160	            <chakra.div sx={closeButtonStyles}>
161	              <ZimmButton variant="icon" icon="close" label="Close" onClick={onClose} />
162	            </chakra.div>
163	          )}
164	          {children}
165	        </MotionChakraDiv>
166	      </chakra.div>
167	    </ModalFocusScope>
168	  );
169	};
170	
171	/**
172	 * Generic right-anchored slide-in drawer shell — overlay, panel, and a Figma-matched size
173	 * variant (see ZimmDrawerSize), built on Chakra's Drawer primitive (focus trap, initial focus,
174	 * focus restore, body-scroll lock, and Escape/overlay-click-to-close all come from Chakra, not
175	 * hand-rolled).
176	 *
177	 * Pass `title` to render an inline header row (title text left, close button right) sized per the
178	 * Figma drawer/header frames. Omit `title` and pass `labelledBy`/`aria-label` instead for drawers
179	 * that supply their own header (e.g. ZimmPdpDrawer's tab row), which keeps the floating close
180	 * button behaviour.
181	 *
182	 * @param props see ZimmDrawerProps
183	 */
184	export const ZimmDrawer = (props: ZimmDrawerProps) => {
185	  const { isOpen, onClose, size, children, titleStyle = 'large', finalFocusRef, initialFocusRef } = props;
186	  const styles = useMultiStyleConfig(ZIMM_DRAWER_RECIPE, { variant: size });
187	  const titleId = useId();
188	
189	  const title = 'title' in props ? props.title : undefined;
190	  const labelledBy = !title && 'labelledBy' in props ? props.labelledBy : undefined;
191	  const ariaLabel = !title && 'aria-label' in props ? props['aria-label'] : undefined;
192	
193	  // Chakra's FocusLock remains active during the exit animation, so any focus call made
194	  // while the drawer is still mounted (rAF, close-button onClick) gets trapped and dropped.
195	  // onCloseComplete fires after the animation finishes and FocusLock is released — the only
196	  // reliable moment to restore focus. Covers both close-button click and Escape for all
197	  // consumers that pass finalFocusRef.
198	  const handleCloseComplete = () => {
199	    if (finalFocusRef) finalFocusRef.current?.focus();
200	  };
201	
202	  return (
203	    <Drawer
204	      isOpen={isOpen}
205	      onClose={onClose}
206	      placement="right"
207	      onCloseComplete={handleCloseComplete}
208	      initialFocusRef={initialFocusRef}
209	    >
210	      <DrawerOverlay sx={styles.overlay} />
211	      {/* aria-labelledby (not aria-label) for the title case: Chakra's own <DrawerContent>
212	          would clobber it with its own headingId (undefined without a DrawerHeader), but
213	          ZimmDrawerContent bypasses <DrawerContent> entirely and sets dialogProps itself
214	          (see its own comment above) — the clobbering bug this would otherwise work around
215	          doesn't apply here, so referencing the visible title node is safe and preferred. */}
216	      <ZimmDrawerContent
217	        onClose={onClose}
218	        title={title}
219	        titleId={title ? titleId : undefined}
220	        titleStyle={titleStyle}
221	        labelledBy={labelledBy}
222	        ariaLabel={ariaLabel}
223	        contentStyles={styles.content}
224	        headerStyles={styles.header}
225	        headerTitleStyles={styles.headerTitle}
226	        closeButtonStyles={styles.closeButton}
227	      >
228	        {children}
229	      </ZimmDrawerContent>
230	    </Drawer>
231	  );
232	};
