32	  play: async () => {
33	    // Portal renders outside canvasElement — testing.md §Layer-2 exception. Chakra's Drawer is
34	    // built on its Modal primitive, which renders DrawerContent via a Portal by default, so
35	    // within(canvasElement) can't reach it.
36	    const doc = within(document.body);
